"""Build a self-contained offline reading/comparison document, no network assets."""
from pathlib import Path
import re,json,html
from build_delivery import clean_old
R=Path(__file__).resolve().parents[1]
def j(p):return json.loads((R/p).read_text(encoding='utf-8'))
def esc(s):return html.escape(s,quote=True)
def paragraphs(s):
    return ''.join('<p>'+esc(re.sub(r'[*`_]','',p.strip()))+'</p>' for p in s.split('\n\n') if p.strip())
def main():
    beads=j('editorial/FINAL_BEADS.json');cards=j('editorial/evidence_cards.json')
    ranges=j('sources/structure.json')['frozen_segments'];choices=j('editorial/old_excerpt_choices.json')
    old=(R/'baseline_package/out/READER_v3.md').read_text(encoding='utf-8-sig')
    parts={m[1]:clean_old(m[2]) for m in re.finditer(r'^## (S\d\d)\b[^\n]*\n(.*?)(?=^## S\d\d\b|\Z)',old,re.M|re.S)}
    nav=[];sections=[]
    for i,(b,(rng,label)) in enumerate(zip(beads,ranges)):
        sid=b['segment'];card=cards[sid]
        nav.append(f'<button class="chapter" data-index="{i}" aria-pressed="{str(i==0).lower()}"><span>{sid} · {rng}</span>{esc(b["title"])}</button>')
        selected=[]
        for needle in choices[sid]:
            hit=[p for p in parts[sid].split('\n\n') if needle in p]
            assert len(hit)==1
            selected.append(hit[0])
        quotes=''.join('<blockquote>'+esc(re.sub(r'[*`_]','',q))+f'<cite><a href="sources/{uid.rsplit("-U",1)[0]}.md">{esc(uid)}</a></cite></blockquote>' for uid,q in card['quotes'])
        sections.append(f'''<section class="bead" id="{sid}" {'hidden' if i else ''}>
<header class="bead-head"><div class="eyebrow">{sid} · 第{rng.replace('-','–')}小节 · {esc(label)}</div><h2 tabindex="-1">{esc(b['title'])}</h2></header>
<div class="single-reader">{paragraphs(b['body'])}</div>
<div class="comparison"><div class="columns"><article><h3>原A · 具体的原料</h3>{quotes}</article><article><h3>上一版 · 完整段落摘选</h3>{paragraphs(chr(10).join([s+'\n' for s in selected]))}<a class="full-link" href="baseline_package/beads/STEP4_{sid}.md">查看上一版完整珠子 ↗</a></article><article class="new"><h3>新版 · 完整正文</h3>{paragraphs(b['body'])}</article></div><aside class="decision"><strong>取舍与代价</strong><p>{esc(card['change'])}</p></aside></div>
</section>''')
    page='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>船歌 · 十四颗珠子</title><style>
:root{color-scheme:light;--paper:#f6f3eb;--ink:#203b37;--muted:#69736a;--line:#d9ded2;--accent:#31695e}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:"Microsoft YaHei","PingFang SC",sans-serif}button,a{-webkit-tap-highlight-color:transparent}button{font:inherit;cursor:pointer}a{color:var(--accent);text-underline-offset:4px}button:focus-visible,a:focus-visible{outline:2px solid #bc803b;outline-offset:3px}.masthead{padding:38px 48px 28px;border-bottom:1px solid var(--line);display:flex;gap:32px;align-items:flex-end;justify-content:space-between}.eyebrow{font-size:12px;letter-spacing:.12em;color:var(--muted)}h1{font-family:"Songti SC",SimSun,serif;font-size:34px;font-weight:500;margin:12px 0}h1 small{font-size:17px;letter-spacing:.08em;margin-left:10px}.intro{max-width:720px;color:var(--muted);font-size:13px;line-height:1.9;margin:0}.mode{display:flex;border:1px solid var(--line);border-radius:8px;padding:4px;white-space:nowrap;align-self:flex-end}.mode button{border:0;background:none;color:var(--muted);padding:10px 18px;border-radius:5px}.mode button[aria-pressed=true]{background:var(--ink);color:white}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);max-width:1800px;margin:auto}.chapters{padding:24px 18px;border-right:1px solid var(--line)}.chapter{display:block;width:100%;background:none;border:0;border-left:2px solid transparent;text-align:left;padding:12px 14px;line-height:1.7;font-size:12px;color:var(--muted)}.chapter span{display:block;font:10px/1.8 ui-monospace,monospace;letter-spacing:.08em}.chapter[aria-pressed=true]{background:#e9eee4;border-left-color:var(--accent);color:var(--ink)}main{padding:52px 44px 42px;min-height:770px}.bead-head{max-width:690px;margin:0 auto 32px}h2{font-family:"Songti SC",SimSun,serif;font-size:30px;line-height:1.55;font-weight:500;margin:12px 0 0;outline:none}.single-reader{max-width:690px;margin:auto;font-family:"Songti SC",SimSun,serif;font-size:19px;line-height:2.12;letter-spacing:.025em}.single-reader p{margin:0 0 23px}.comparison{display:none}.compare .comparison{display:block}.compare .single-reader{display:none}.compare .bead-head{max-width:none}.columns{display:grid;grid-template-columns:1fr 1.1fr 1.1fr;gap:24px}.columns article{font-size:14px;line-height:1.95;min-width:0}.columns article.new{background:#eaf0e5;padding:0 20px 12px;margin:0 -8px;border-radius:6px}h3{font-size:12px;letter-spacing:.1em;border-bottom:1px solid var(--line);padding:14px 0;margin:0 0 23px;color:var(--muted)}blockquote{margin:0 0 28px;font-family:"Songti SC",SimSun,serif;font-size:16px;line-height:1.9}cite{display:block;margin-top:9px;font:9px/1.8 ui-monospace,monospace;font-style:normal;word-break:break-all}.full-link{font-size:11px}.decision{margin-top:30px;border-top:1px solid var(--line);padding-top:20px;font-size:13px;line-height:1.9}.decision strong{font-weight:500}.decision p{color:var(--muted);margin:8px 0}.pager{max-width:690px;margin:40px auto 0;display:flex;align-items:center;gap:15px;padding-top:22px;border-top:1px solid var(--line)}.pager button{border:1px solid var(--line);background:transparent;color:var(--ink);padding:8px 16px;border-radius:5px;font-size:12px}.pager button:disabled{opacity:.35;cursor:default}.count{margin-left:auto;color:var(--muted);font:11px ui-monospace,monospace}footer{border-top:1px solid var(--line);padding:22px 48px;font-size:11px;line-height:1.9;color:var(--muted)}footer a{margin-right:20px} [hidden]{display:none!important}
@media(max-width:1150px){.layout{grid-template-columns:210px minmax(0,1fr)}main{padding:38px 28px}.columns{grid-template-columns:1fr}.columns article{font-size:16px}.columns article.new{margin:0;padding:0 20px 12px}.masthead{padding:28px}.chapters{padding:20px 8px}}
@media(max-width:700px){.masthead{display:block;padding:24px 22px}h1{font-size:28px}h1 small{display:block;margin:7px 0 0;font-size:14px}.mode{display:inline-flex;margin-top:18px}.layout{display:block}.chapters{display:flex;overflow-x:auto;border-right:0;border-bottom:1px solid var(--line);padding:10px}.chapter{min-width:168px;border-left:0;border-bottom:2px solid transparent}.chapter[aria-pressed=true]{border-left:0;border-bottom-color:var(--accent)}main{padding:30px 23px;min-height:600px}h2{font-size:26px}.single-reader{font-size:18px;line-height:2.05}footer{padding:20px 24px}}
@media print{.masthead{padding:0 0 20px}.mode,.chapters,.pager,footer{display:none}.layout{display:block}main{padding:0}.bead[hidden]{display:block!important}.bead{page-break-inside:avoid;margin-top:32px}.comparison{display:none!important}.single-reader{display:block!important;max-width:none;font-size:13px}.bead-head{max-width:none}h2{font-size:20px}}
</style></head><body><header class="masthead"><div><div class="eyebrow">CHOPIN · BARCAROLLE · OP.60</div><h1>船歌 <small>十四颗珠子</small></h1><p class="intro">从原始研究里，留下人物的距离、身体的触感和声音的变化。先读新版，再切换对照，看看哪些东西回来了，哪些被舍下。</p></div><div class="mode" role="group" aria-label="阅读方式"><button id="read" aria-pressed="true">读新版</button><button id="compare" aria-pressed="false">看对照</button></div></header><div class="layout"><nav class="chapters" aria-label="十四个音乐段落">NAV</nav><main>SECTIONS<div class="pager"><button id="prev">← 上一段</button><button id="next">下一段 →</button><span class="count" aria-live="polite">01 / 14</span></div></main></div><footer>主编辑整合与精编 · 固定PTNA／朝山十四段 · 情景为聆听比喻 · 原始模型响应另存 · 离线阅读，无外部资源<br><a href="READ_ME_FIRST.md">交付说明</a><a href="MODEL_METHOD_COMPARISON.md">真实模型对照</a><a href="SOURCES_AND_LIMITS.md">来源与条件</a><a href="READER.md">Markdown全文</a></footer><script>
const sections=[...document.querySelectorAll('.bead')],chapters=[...document.querySelectorAll('.chapter')];let current=0;
function show(i,focus=false){current=Math.max(0,Math.min(sections.length-1,i));sections.forEach((s,n)=>s.hidden=n!==current);chapters.forEach((b,n)=>b.setAttribute('aria-pressed',String(n===current)));document.querySelector('.count').textContent=String(current+1).padStart(2,'0')+' / 14';document.querySelector('#prev').disabled=current===0;document.querySelector('#next').disabled=current===13;history.replaceState(null,'','#'+sections[current].id);if(focus)sections[current].querySelector('h2').focus({preventScroll:true})}
chapters.forEach((b,i)=>b.addEventListener('click',()=>show(i,true)));document.querySelector('#prev').addEventListener('click',()=>show(current-1,true));document.querySelector('#next').addEventListener('click',()=>show(current+1,true));['read','compare'].forEach(mode=>document.getElementById(mode).addEventListener('click',()=>{document.body.classList.toggle('compare',mode==='compare');['read','compare'].forEach(id=>document.getElementById(id).setAttribute('aria-pressed',String(id===mode)))}));const initial=sections.findIndex(s=>'#'+s.id===location.hash);show(initial<0?0:initial);if(new URLSearchParams(location.search).get('view')==='compare')document.getElementById('compare').click();
</script></body></html>'''
    page=page.replace('NAV',''.join(nav)).replace('SECTIONS',''.join(sections))
    (R/'阅读与对照.html').write_text(page,encoding='utf-8',newline='\n')
    print('Offline reading document: 14 chapters, 2 views, 0 external assets.')
if __name__=='__main__':main()
